create or replace TABLE LDL_DATA_PRODUCTION.FE_MSTR_TEMP.T_MLY_PROT_FACT_WRITE_OFF_BY_ORGANIZATION_DAY_WAWI_PRODUCT cluster by (BUS_DT)(
	BUS_DT DATE NOT NULL COMMENT 'The business date to which the measures are related.',
	INT_ORG_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the store or warehouse, where the product had to be written off.',
	INT_ORG_TYPE_CD VARCHAR(20) NOT NULL COMMENT 'The code identifying the discriminators for internal organizations.',
	COUNTRY_ORG_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the country organization. This is on the one hand related to the country organization which is responsible for the store which has sold the product, and on the other hand to the country organization which has defined the local properties of the product.',
	COUNTRY_ORG_CD VARCHAR(2) NOT NULL COMMENT 'The code of the business country for which the related country organization is responsible. (The business country is not identical to a political country.) This is on the one hand related to the country organization which is responsible for the store which has sold the product, and on the other hand to the country organization which has defined the local properties of the product.',
	WAWI_VARIANT_SID NUMBER(38,0) NOT NULL,
	WAWI_PRODUCT_SID NUMBER(38,0) NOT NULL,
	WRITE_OFF_FOR_BREAKAGE_NET_VAL NUMBER(38,5) COMMENT 'The net amount in the given currency which was written off in this internal organization (i.e. store or warehouse) for the given product on that day because of breakage. (In case the internal organization references a warehouse, this is only that portion of the write-offs which happened directly in the warehouse. Write-offs in stores which are managed by this warehouse, are not included.)',
	WRITE_OFF_FOR_SELL_BY_DT_NET_VAL NUMBER(38,5) COMMENT 'The net amount in the given currency which was written off in this internal organization (i.e. store or warehouse) for the given product on that day because the sell-by-date has been exceeded. (In case the internal organization references a warehouse, this is only that portion of the write-offs which happened directly in the warehouse. Write-offs in stores which are managed by this warehouse, are not included.)',
	WRITE_OFF_FOR_DELIV_QUALITY_NET_VAL NUMBER(38,5) COMMENT 'The net amount in the given currency which was written off in this internal organization (i.e. store or warehouse) for the given product on that day because of quality issues of delivered products. (In case the internal organization references a warehouse, this is only that portion of the write-offs which happened directly in the warehouse. Write-offs in stores which are managed by this warehouse, are not included.)',
	WRITE_OFF_FOR_DEFECTIVE_NON_FOOD_NET_VAL NUMBER(38,5) COMMENT 'The net amount in the given currency which was written off in this internal organization (i.e. store or warehouse) for the given product on that day because of defective non-food produts. (In case the internal organization references a warehouse, this is only that portion of the write-offs which happened directly in the warehouse. Write-offs in stores which are managed by this warehouse, are not included.)',
	WRITE_OFF_FOR_DONATIONS_NET_VAL NUMBER(38,5) COMMENT 'The net amount in the given currency which was written off in this internal organization (i.e. store or warehouse) for the given product on that day because of donations to charitable organizations. (In case the internal organization references a warehouse, this is only that portion of the write-offs which happened directly in the warehouse. Write-offs in stores which are managed by this warehouse, are not included.)',
	WRITE_OFF_FOR_TAKEN_PROD_NET_VAL NUMBER(38,5) COMMENT 'The net amount in the given currency which was written off in this internal organization (i.e. store or warehouse) for the given product on that day because products were taken, e.g. for the purpose of quality sampling. (In case the internal organization references a warehouse, this is only that portion of the write-offs which happened directly in the warehouse. Write-offs in stores which are managed by this warehouse, are not included.)',
	WRITE_OFF_FOR_DISCOUNTS_NET_VAL NUMBER(38,5) COMMENT 'The net amount in the given currency which was written off in this internal organization (i.e. store or warehouse) for the given product on that day because of discounts. Discounts can be given for perishable products in case the sell-by-date is near. (In case the internal organization references a warehouse, this is only that portion of the write-offs which happened directly in the warehouse. Write-offs in stores which are managed by this warehouse, are not included.)',
	CURR_CD VARCHAR(3) NOT NULL COMMENT 'The code identifying the currency according to ISO-4217.',
	DWH_CREATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created in the data warehouse.',
	DWH_UPDATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created or last updated.',
	DWH_LOAD_ID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier of the batch load which has done the last update to this record. (Closing a record in history without updating any payload columns does not trigger an update of the dwh_load_id.)',
	DWH_NODE_CD VARCHAR(20) NOT NULL COMMENT 'The code for the source system (or slice of source system) from which this record was loaded.',
	WRITE_OFF_NET_VAL NUMBER(38,5) COMMENT 'The total net amount in the given currency which was written off in this internal organization (i.e. store or warehouse) for the given product on that day, independent on the reason. (In case the internal organization references a warehouse, this is only that portion of the write-offs which happened directly in the warehouse. Write-offs in stores which are managed by this warehouse, are not included.)',
	WRITE_OFF_FOR_FORCE_MAJEURE_NET_VAL NUMBER(38,5) COMMENT 'The net amount in the given currency which was written off in this internal organization (i.e. store or warehouse) for the given product on that day because of force majeure. (In case the internal organization references a warehouse, this is only that portion of the write-offs which happened directly in the warehouse. Write-offs in stores which are managed by this warehouse, are not included.)',
	WRITE_OFF_FOR_STOCK_CLEARANCE_NET_VAL NUMBER(38,5) COMMENT 'The net amount in the given currency which was written off in this internal organization (i.e. store or warehouse) for the given product on that day because of stock clearance. (In case the internal organization references a warehouse, this is only that portion of the write-offs which happened directly in the warehouse. Write-offs in stores which are managed by this warehouse, are not included.)',
	constraint PK_T_FACT_WRITE_OFF_BY_ORGANIZATION_DAY_PRODUCT primary key (BUS_DT, INT_ORG_SID, WAWI_VARIANT_SID)
)COMMENT='An aggregate fact holding write-offs and turnover per day, product (logistic variant) and internal organization (store or warehouse).'
;